import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Check, X, Trash2, Save, Users, MessageSquare, Clock, ShieldCheck, FileCode, Lightbulb, Undo2, Gamepad2, Plus, Upload, Download } from "lucide-react";
import NavBar from "@/components/NavBar";
import {
  api,
  listGames,
  getGame,
  ownerListUsers,
  ownerSetUserStatus,
  ownerDeleteUser,
  ownerListSuggestions,
  ownerUpdateSuggestion,
  ownerDeleteSuggestion,
  ownerCreateGame,
  ownerUpdateGame,
  ownerDeleteGame,
  ownerImportBackup,
} from "@/lib/api";

const PAGE_TABS = [
  { key: "chat", label: "Chat HTML" },
  { key: "community", label: "Community Games HTML" },
  { key: "gamemaker", label: "Game Maker HTML" },
  { key: "party", label: "Party Games HTML" },
];

function downloadSiteShortcut() {
  const siteUrl = `${window.location.origin}/`;
  const iconUrl = `${window.location.origin}/icons/icon-192.png`;
  const shortcut = [
    "[InternetShortcut]",
    `URL=${siteUrl}`,
    `IconFile=${iconUrl}`,
    "IconIndex=0",
    "",
  ].join("\r\n");
  const blob = new Blob([shortcut], { type: "application/internet-shortcut" });
  const href = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = href;
  link.download = "Learning Games.url";
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(href), 1000);
}

export default function OwnerPanel() {
  const [users, setUsers] = useState([]);
  const [suggestions, setSuggestions] = useState([]);
  const [games, setGames] = useState([]);
  const [pageHtml, setPageHtml] = useState({ chat: "", community: "", gamemaker: "", party: "" });
  const [activePage, setActivePage] = useState("chat");
  const [loading, setLoading] = useState(true);
  const [savingHtml, setSavingHtml] = useState(false);
  const [tab, setTab] = useState("users");
  const [newGame, setNewGame] = useState({ name: "", html: "" });
  const [addingGame, setAddingGame] = useState(false);
  const [gameFilter, setGameFilter] = useState("");
  const [editingGame, setEditingGame] = useState(null); // { slug, name, html }
  const [savingGame, setSavingGame] = useState(false);
  const [importingBackup, setImportingBackup] = useState(false);
  const [importSummary, setImportSummary] = useState(null);
  const [installPrompt, setInstallPrompt] = useState(null);
  const [installStatus, setInstallStatus] = useState("ready");

  const refresh = async () => {
    try {
      const [u, chat, community, gamemaker, party, s, g] = await Promise.all([
        ownerListUsers(),
        api.get("/pages/chat"),
        api.get("/pages/community"),
        api.get("/pages/gamemaker"),
        api.get("/pages/party"),
        ownerListSuggestions(),
        listGames(),
      ]);
      setUsers(u);
      setSuggestions(s);
      setGames(g);
      setPageHtml({
        chat: chat.data.html || "",
        community: community.data.html || "",
        gamemaker: gamemaker.data.html || "",
        party: party.data.html || "",
      });
    } catch {
      toast.error("Could not load owner data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    refresh();
  }, []);

  useEffect(() => {
    const standalone =
      window.matchMedia?.("(display-mode: standalone)")?.matches ||
      window.navigator.standalone;
    if (standalone) {
      setInstallStatus("installed");
    } else if (window.learningGamesInstallPrompt) {
      setInstallPrompt(window.learningGamesInstallPrompt);
      setInstallStatus("available");
    }

    const onInstallReady = (event) => {
      const prompt = event.detail || window.learningGamesInstallPrompt;
      if (!prompt) return;
      setInstallPrompt(prompt);
      setInstallStatus("available");
    };
    const onAppInstalled = () => {
      setInstallPrompt(null);
      setInstallStatus("installed");
      toast.success("Site installed");
    };

    window.addEventListener("learninggames:install-ready", onInstallReady);
    window.addEventListener("learninggames:installed", onAppInstalled);
    return () => {
      window.removeEventListener("learninggames:install-ready", onInstallReady);
      window.removeEventListener("learninggames:installed", onAppInstalled);
    };
  }, []);

  const pending = useMemo(() => users.filter((u) => u.status === "pending"), [users]);
  const approved = useMemo(() => users.filter((u) => u.status === "approved" && u.role !== "owner"), [users]);
  const rejected = useMemo(() => users.filter((u) => u.status === "rejected"), [users]);
  const openSuggestions = useMemo(() => suggestions.filter((s) => s.status === "open"), [suggestions]);
  const closedSuggestions = useMemo(() => suggestions.filter((s) => s.status !== "open"), [suggestions]);

  const suggAct = async (id, action) => {
    try {
      await ownerUpdateSuggestion(id, action);
      toast.success(action === "done" ? "Marked as added" : action === "dismiss" ? "Dismissed" : "Reopened");
      refresh();
    } catch {
      toast.error("Action failed");
    }
  };

  const suggDelete = async (id, name) => {
    if (!window.confirm(`Delete suggestion "${name}"?`)) return;
    try {
      await ownerDeleteSuggestion(id);
      toast.success("Suggestion deleted");
      refresh();
    } catch {
      toast.error("Delete failed");
    }
  };

  const act = async (id, action) => {
    try {
      await ownerSetUserStatus(id, action);
      toast.success(action === "approve" ? "User approved" : "User rejected");
      refresh();
    } catch {
      toast.error("Action failed");
    }
  };

  const remove = async (id, username) => {
    if (!window.confirm(`Delete account @${username}? This cannot be undone.`)) return;
    try {
      await ownerDeleteUser(id);
      toast.success("Account deleted");
      refresh();
    } catch {
      toast.error("Delete failed");
    }
  };

  const saveHtml = async () => {
    setSavingHtml(true);
    try {
      await api.put(`/owner/pages/${activePage}`, { html: pageHtml[activePage] });
      toast.success(`${PAGE_TABS.find((p) => p.key === activePage).label} updated`);
    } catch {
      toast.error("Could not save HTML");
    } finally {
      setSavingHtml(false);
    }
  };

  const addGame = async () => {
    const name = newGame.name.trim();
    const html = newGame.html.trim();
    if (!name || !html) {
      toast.error("Name and HTML are required");
      return;
    }
    setAddingGame(true);
    try {
      const created = await ownerCreateGame(name, html);
      toast.success(`Added "${created.name}"`);
      setNewGame({ name: "", html: "" });
      refresh();
    } catch (e) {
      toast.error(e?.response?.data?.detail || "Could not add game");
    } finally {
      setAddingGame(false);
    }
  };

  const removeGame = async (slug, name) => {
    if (!window.confirm(`Delete game "${name}"? This cannot be undone.`)) return;
    try {
      await ownerDeleteGame(slug);
      toast.success("Game deleted");
      if (editingGame?.slug === slug) setEditingGame(null);
      refresh();
    } catch {
      toast.error("Delete failed");
    }
  };

  const beginEditGame = async (slug) => {
    try {
      const full = await getGame(slug);
      setEditingGame({ slug: full.slug, name: full.name, html: full.html });
      // Scroll form into view for convenience
      setTimeout(() => {
        document.getElementById("owner-game-form")?.scrollIntoView({ behavior: "smooth", block: "start" });
      }, 50);
    } catch {
      toast.error("Could not load game");
    }
  };

  const cancelEditGame = () => setEditingGame(null);

  const saveEditGame = async () => {
    if (!editingGame) return;
    const name = editingGame.name.trim();
    const html = editingGame.html.trim();
    if (!name || !html) {
      toast.error("Name and HTML are required");
      return;
    }
    setSavingGame(true);
    try {
      await ownerUpdateGame(editingGame.slug, name, html);
      toast.success(`Saved "${name}"`);
      setEditingGame(null);
      refresh();
    } catch (e) {
      toast.error(e?.response?.data?.detail || "Could not save game");
    } finally {
      setSavingGame(false);
    }
  };

  const importBackup = async (file) => {
    if (!file) return;
    if (!file.name.toLowerCase().endsWith(".zip")) {
      toast.error("Upload a .zip backup file");
      return;
    }
    if (!window.confirm(`Import "${file.name}" and replace the current game library with the backup?`)) return;
    setImportingBackup(true);
    setImportSummary(null);
    try {
      const summary = await ownerImportBackup(file);
      setImportSummary(summary);
      toast.success(`Imported ${summary.games.toLocaleString()} games`);
      await refresh();
    } catch (e) {
      toast.error(e?.response?.data?.detail || "Backup import failed");
    } finally {
      setImportingBackup(false);
    }
  };

  const installSite = async () => {
    if (installStatus === "installed") {
      toast.info("This site is already installed.");
      return;
    }
    const prompt = installPrompt || window.learningGamesInstallPrompt;
    if (!prompt) {
      downloadSiteShortcut();
      toast.success("Downloaded a shortcut. Browser app install is not available here.");
      return;
    }
    try {
      await prompt.prompt();
      const choice = await prompt.userChoice;
      setInstallPrompt(null);
      window.learningGamesInstallPrompt = null;
      if (choice?.outcome === "accepted") {
        setInstallStatus("installed");
        toast.success("Install started");
      } else {
        toast.info("Install canceled");
      }
    } catch {
      toast.error("Install prompt was not available.");
    }
  };

  const filteredGames = useMemo(() => {
    const q = gameFilter.trim().toLowerCase();
    if (!q) return games;
    return games.filter((g) => g.name.toLowerCase().includes(q) || g.slug.includes(q));
  }, [games, gameFilter]);
  const installButtonText =
    installStatus === "installed"
      ? "Installed"
      : installStatus === "available" || installPrompt
      ? "Install app"
      : "Download shortcut";

  return (
    <div className="min-h-screen bg-[#fff7f0]">
      <NavBar />
      <main className="max-w-6xl mx-auto px-5 sm:px-8 py-10">
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className="grid place-items-center w-9 h-9 rounded-xl bg-[#1a1613] text-[#ff6a00]">
                <ShieldCheck size={18} />
              </span>
              <h1 className="font-display text-3xl sm:text-4xl font-extrabold tracking-tight">
                Owner panel
              </h1>
            </div>
            <p className="text-[#5c534d]">
              Approve members, import backups, edit pages, and manage the game catalog.
            </p>
          </div>
          <button
            onClick={installSite}
            data-testid="owner-install-site-btn"
            className="inline-flex items-center justify-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] transition-colors disabled:opacity-60"
            title={installButtonText === "Download shortcut" ? "Download a Windows shortcut to this site" : "Install this site as an app"}
          >
            <Download size={15} />
            {installButtonText}
          </button>
        </div>

        <div className="mt-6 flex items-center gap-2 border-b border-[#efe3d6]">
          <TabBtn active={tab === "users"} onClick={() => setTab("users")} testId="tab-users">
            <Users size={14} /> Users
            <span className="ml-1 text-[10px] font-bold bg-[#ff6a00] text-white rounded-full px-1.5 py-0.5">
              {pending.length}
            </span>
          </TabBtn>
          <TabBtn active={tab === "chat"} onClick={() => setTab("chat")} testId="tab-chat">
            <FileCode size={14} /> Page HTML
          </TabBtn>
          <TabBtn active={tab === "games"} onClick={() => setTab("games")} testId="tab-games">
            <Gamepad2 size={14} /> Games
            <span className="ml-1.5 text-[10px] font-bold bg-[#1a1613] text-white rounded-full px-1.5 py-0.5">
              {games.length}
            </span>
          </TabBtn>
          <TabBtn active={tab === "suggestions"} onClick={() => setTab("suggestions")} testId="tab-suggestions">
            <Lightbulb size={14} /> Suggestions
            {openSuggestions.length > 0 && (
              <span className="ml-1 text-[10px] font-bold bg-[#ff6a00] text-white rounded-full px-1.5 py-0.5">
                {openSuggestions.length}
              </span>
            )}
          </TabBtn>
        </div>

        {loading ? (
          <div className="mt-10 text-[#5c534d]">Loading…</div>
        ) : tab === "users" ? (
          <div className="mt-8 space-y-8">
            <UserSection
              title="Pending"
              icon={<Clock size={14} />}
              users={pending}
              empty="No one is waiting."
              renderActions={(u) => (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => act(u.id, "approve")}
                    data-testid={`approve-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#ff6a00] text-white text-xs font-semibold hover:bg-[#e85d00] transition-colors"
                  >
                    <Check size={13} /> Approve
                  </button>
                  <button
                    onClick={() => act(u.id, "reject")}
                    data-testid={`reject-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-red-400 hover:text-red-500 transition-colors"
                  >
                    <X size={13} /> Reject
                  </button>
                </div>
              )}
            />

            <UserSection
              title="Approved"
              icon={<Check size={14} />}
              users={approved}
              empty="No approved members yet."
              renderActions={(u) => (
                <div className="flex items-center gap-2">
                  <button
                    onClick={async () => {
                      if (!window.confirm(`Promote @${u.username} to OWNER? They'll have full owner access.`)) return;
                      try {
                        await api.post(`/owner/users/${u.id}/role`, { role: "owner" });
                        toast.success(`@${u.username} is now an owner`);
                        refresh();
                      } catch { toast.error("Promote failed"); }
                    }}
                    data-testid={`promote-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-[#ff6a00] hover:text-[#ff6a00] transition-colors"
                  >
                    <ShieldCheck size={13} /> Make owner
                  </button>
                  <button
                    onClick={() => act(u.id, "reject")}
                    data-testid={`revoke-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-red-400 hover:text-red-500 transition-colors"
                  >
                    <X size={13} /> Revoke
                  </button>
                  <button
                    onClick={() => remove(u.id, u.username)}
                    data-testid={`delete-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[#5c534d] hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Delete account"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              )}
            />

            <UserSection
              title="Rejected"
              icon={<X size={14} />}
              users={rejected}
              empty="Nobody rejected."
              renderActions={(u) => (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => act(u.id, "approve")}
                    data-testid={`reinstate-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#ff6a00] text-white text-xs font-semibold hover:bg-[#e85d00] transition-colors"
                  >
                    <Check size={13} /> Reinstate
                  </button>
                  <button
                    onClick={() => remove(u.id, u.username)}
                    data-testid={`delete-${u.username}`}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[#5c534d] hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Delete account"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              )}
            />
          </div>
        ) : tab === "chat" ? (
          <div className="mt-8">
            <div className="flex items-center gap-2 flex-wrap mb-4">
              {PAGE_TABS.map((p) => (
                <button
                  key={p.key}
                  onClick={() => setActivePage(p.key)}
                  data-testid={`page-picker-${p.key}`}
                  className={`px-4 py-2 rounded-full text-sm font-semibold transition-colors ${
                    activePage === p.key
                      ? "bg-[#ff6a00] text-white"
                      : "bg-white border border-[#efe3d6] text-[#5c534d] hover:border-[#ff6a00] hover:text-[#ff6a00]"
                  }`}
                >
                  {p.label}
                </button>
              ))}
            </div>
            <label className="block">
              <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">
                {PAGE_TABS.find((p) => p.key === activePage).label}
              </span>
              <textarea
                data-testid={`page-html-textarea-${activePage}`}
                value={pageHtml[activePage]}
                onChange={(e) =>
                  setPageHtml({ ...pageHtml, [activePage]: e.target.value })
                }
                spellCheck={false}
                className="mt-2 w-full min-h-[420px] font-mono text-sm p-4 rounded-xl border border-[#efe3d6] bg-white focus:outline-none focus:ring-2 focus:ring-[#ff6a00] focus:border-[#ff6a00]"
                placeholder="<!DOCTYPE html><html>… paste your HTML here …</html>"
              />
            </label>
            <div className="mt-3 flex items-center justify-between">
              <p className="text-xs text-[#5c534d]">
                Rendered inside a sandboxed iframe on the /{activePage} page.
              </p>
              <button
                onClick={saveHtml}
                disabled={savingHtml}
                data-testid={`save-html-btn-${activePage}`}
                className="inline-flex items-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] disabled:opacity-60 transition-colors"
              >
                <Save size={14} /> {savingHtml ? "Saving…" : "Save HTML"}
              </button>
            </div>
          </div>
        ) : tab === "games" ? (
          <GamesPanel
            games={filteredGames}
            totalCount={games.length}
            filter={gameFilter}
            setFilter={setGameFilter}
            newGame={newGame}
            setNewGame={setNewGame}
            editing={editingGame}
            setEditing={setEditingGame}
            addGame={addGame}
            saveEdit={saveEditGame}
            adding={addingGame}
            saving={savingGame}
            beginEdit={beginEditGame}
            cancelEdit={cancelEditGame}
            removeGame={removeGame}
            importBackup={importBackup}
            importingBackup={importingBackup}
            importSummary={importSummary}
          />
        ) : (
          <div className="mt-8" data-testid="suggestions-panel">
            <SuggestionSection
              title="Open"
              icon={<Clock size={14} />}
              items={openSuggestions}
              empty="No pending suggestions."
              renderActions={(s) => (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => suggAct(s.id, "done")}
                    data-testid={`sugg-done-${s.id}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#ff6a00] text-white text-xs font-semibold hover:bg-[#e85d00] transition-colors"
                  >
                    <Check size={13} /> Added
                  </button>
                  <button
                    onClick={() => suggAct(s.id, "dismiss")}
                    data-testid={`sugg-dismiss-${s.id}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-red-400 hover:text-red-500 transition-colors"
                  >
                    <X size={13} /> Dismiss
                  </button>
                  <button
                    onClick={() => suggDelete(s.id, s.game_name)}
                    data-testid={`sugg-delete-${s.id}`}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[#5c534d] hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Delete"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              )}
            />
            <div className="h-8" />
            <SuggestionSection
              title="Archived"
              icon={<Check size={14} />}
              items={closedSuggestions}
              empty="Nothing archived yet."
              renderActions={(s) => (
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => suggAct(s.id, "reopen")}
                    data-testid={`sugg-reopen-${s.id}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-[#ff6a00] hover:text-[#ff6a00] transition-colors"
                  >
                    <Undo2 size={13} /> Reopen
                  </button>
                  <button
                    onClick={() => suggDelete(s.id, s.game_name)}
                    data-testid={`sugg-delete-${s.id}`}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[#5c534d] hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Delete"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              )}
            />
          </div>
        )}
      </main>
    </div>
  );
}

const TabBtn = ({ active, onClick, testId, children }) => (
  <button
    onClick={onClick}
    data-testid={testId}
    className={`inline-flex items-center gap-1.5 px-4 py-2 -mb-px border-b-2 text-sm font-semibold transition-colors ${
      active
        ? "border-[#ff6a00] text-[#1a1613]"
        : "border-transparent text-[#5c534d] hover:text-[#1a1613]"
    }`}
  >
    {children}
  </button>
);

const UserSection = ({ title, icon, users, empty, renderActions }) => (
  <section data-testid={`section-${title.toLowerCase()}`}>
    <div className="flex items-center gap-2 mb-3">
      <span className="grid place-items-center w-6 h-6 rounded-md bg-[#ffe4d1] text-[#ff6a00]">
        {icon}
      </span>
      <h2 className="font-display font-bold text-lg tracking-tight">{title}</h2>
      <span className="text-xs text-[#5c534d]">{users.length}</span>
    </div>    {users.length === 0 ? (
      <div className="text-sm text-[#5c534d] italic bg-white border border-dashed border-[#efe3d6] rounded-2xl px-4 py-6">
        {empty}
      </div>
    ) : (
      <div className="bg-white border border-[#efe3d6] rounded-2xl divide-y divide-[#efe3d6] overflow-hidden">
        {users.map((u) => (
          <div key={u.id} className="flex items-center justify-between gap-3 px-4 py-3">
            <div className="min-w-0">
              <div className="font-semibold text-[#1a1613] truncate">
                @{u.username}
              </div>
              <div className="text-xs text-[#5c534d]">
                joined {u.created_at ? new Date(u.created_at).toLocaleDateString() : "—"}
              </div>
            </div>
            {renderActions(u)}
          </div>
        ))}
      </div>
    )}
  </section>
);


const SuggestionSection = ({ title, icon, items, empty, renderActions }) => (
  <section data-testid={`sugg-section-${title.toLowerCase()}`}>
    <div className="flex items-center gap-2 mb-3">
      <span className="grid place-items-center w-6 h-6 rounded-md bg-[#ffe4d1] text-[#ff6a00]">
        {icon}
      </span>
      <h2 className="font-display font-bold text-lg tracking-tight">{title}</h2>
      <span className="text-xs text-[#5c534d]">{items.length}</span>
    </div>
    {items.length === 0 ? (
      <div className="text-sm text-[#5c534d] italic bg-white border border-dashed border-[#efe3d6] rounded-2xl px-4 py-6">
        {empty}
      </div>
    ) : (
      <div className="bg-white border border-[#efe3d6] rounded-2xl divide-y divide-[#efe3d6] overflow-hidden">
        {items.map((s) => (
          <div key={s.id} className="flex items-start justify-between gap-3 px-4 py-3">
            <div className="min-w-0">
              <div className="font-semibold text-[#1a1613] truncate">
                {s.game_name}
                <span className="ml-2 text-xs font-normal text-[#5c534d]">
                  from <span className="font-medium">@{s.username}</span>
                </span>
              </div>
              {s.notes && (
                <div className="text-xs text-[#5c534d] mt-1 max-w-2xl whitespace-pre-wrap">
                  {s.notes}
                </div>
              )}
              <div className="text-[10px] text-[#5c534d] mt-1 uppercase tracking-widest">
                {new Date(s.created_at).toLocaleString()} · {s.status}
              </div>
            </div>
            {renderActions(s)}
          </div>
        ))}
      </div>
    )}
  </section>
);


const GamesPanel = ({
  games,
  totalCount,
  filter,
  setFilter,
  newGame,
  setNewGame,
  editing,
  setEditing,
  addGame,
  saveEdit,
  adding,
  saving,
  beginEdit,
  cancelEdit,
  removeGame,
  importBackup,
  importingBackup,
  importSummary,
}) => {
  const inEditMode = !!editing;
  const formTitle = inEditMode ? `Edit "${editing.name || editing.slug}"` : "Add a new game";
  const nameValue = inEditMode ? editing.name : newGame.name;
  const htmlValue = inEditMode ? editing.html : newGame.html;
  const setName = (v) =>
    inEditMode ? setEditing({ ...editing, name: v }) : setNewGame({ ...newGame, name: v });
  const setHtml = (v) =>
    inEditMode ? setEditing({ ...editing, html: v }) : setNewGame({ ...newGame, html: v });

  return (
    <div className="mt-8" data-testid="games-panel">
      <section className="bg-white border border-[#efe3d6] rounded-2xl p-5" data-testid="backup-import-panel">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="grid place-items-center w-8 h-8 rounded-xl bg-[#ffe4d1] text-[#ff6a00]">
                <Upload size={16} />
              </span>
              <h2 className="font-display font-bold text-lg tracking-tight">Import full backup</h2>
            </div>
            <p className="mt-2 text-sm text-[#5c534d] max-w-2xl">
              Upload a site backup zip to restore all games, page HTML, users, suggestions, favorites, and metadata into this app.
            </p>
          </div>
          <label className={`inline-flex items-center justify-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold transition-colors ${importingBackup ? "opacity-60 cursor-wait" : "hover:bg-[#e85d00] cursor-pointer"}`}>
            <Upload size={14} /> {importingBackup ? "Importing..." : "Choose backup zip"}
            <input
              type="file"
              accept=".zip,application/zip"
              disabled={importingBackup}
              onChange={(e) => {
                importBackup(e.target.files?.[0]);
                e.target.value = "";
              }}
              data-testid="backup-import-input"
              className="sr-only"
            />
          </label>
        </div>
        {importSummary && (
          <div className="mt-4 rounded-xl border border-[#efe3d6] bg-[#fff7f0] px-4 py-3 text-sm text-[#5c534d]" data-testid="backup-import-summary">
            Imported <span className="font-semibold text-[#1a1613]">{importSummary.games.toLocaleString()} games</span>,
            {" "}<span className="font-semibold text-[#1a1613]">{importSummary.pages}</span> pages,
            {" "}<span className="font-semibold text-[#1a1613]">{importSummary.users}</span> users,
            {" "}<span className="font-semibold text-[#1a1613]">{importSummary.suggestions}</span> suggestions,
            and <span className="font-semibold text-[#1a1613]">{importSummary.favorites}</span> favorites.
            {importSummary.notes?.length > 0 && (
              <div className="mt-2 text-xs">
                {importSummary.notes[0]}
              </div>
            )}
          </div>
        )}
      </section>

      <section id="owner-game-form" className="mt-8 bg-white border border-[#efe3d6] rounded-2xl p-5">
        <div className="flex items-center justify-between gap-2 mb-4">
          <h2 className="font-display font-bold text-lg tracking-tight" data-testid="games-form-title">
            {formTitle}
          </h2>
          {inEditMode && (
            <button
              onClick={cancelEdit}
              data-testid="cancel-edit-game-btn"
              className="text-xs font-semibold px-3 py-1.5 rounded-full border border-[#efe3d6] hover:border-[#ff6a00] hover:text-[#ff6a00] transition-colors"
            >
              Cancel edit
            </button>
          )}
        </div>
        <div className="grid gap-3">
          <label className="block">
            <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">Title</span>
            <input
              type="text"
              value={nameValue}
              onChange={(e) => setName(e.target.value)}
              data-testid="new-game-name-input"
              placeholder="Slope, Cookie Clicker, Retro Bowl…"
              className="mt-1 w-full px-4 py-2.5 rounded-xl border border-[#efe3d6] bg-white focus:outline-none focus:ring-2 focus:ring-[#ff6a00] focus:border-[#ff6a00]"
            />
          </label>
          <label className="block">
            <span className="text-xs font-semibold uppercase tracking-widest text-[#5c534d]">Game HTML</span>
            <textarea
              value={htmlValue}
              onChange={(e) => setHtml(e.target.value)}
              data-testid="new-game-html-textarea"
              spellCheck={false}
              className="mt-1 w-full min-h-[300px] font-mono text-sm p-4 rounded-xl border border-[#efe3d6] bg-white focus:outline-none focus:ring-2 focus:ring-[#ff6a00] focus:border-[#ff6a00]"
              placeholder="<!DOCTYPE html><html>… paste the full game HTML here …</html>"
            />
          </label>
          <div className="flex items-center justify-between">
            <p className="text-xs text-[#5c534d]">
              {inEditMode
                ? `Slug: /${editing.slug} (unchanged when editing)`
                : "A URL slug is generated from the title automatically."}
            </p>
            {inEditMode ? (
              <button
                onClick={saveEdit}
                disabled={saving}
                data-testid="save-game-btn"
                className="inline-flex items-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] disabled:opacity-60 transition-colors"
              >
                <Save size={14} /> {saving ? "Saving…" : "Save changes"}
              </button>
            ) : (
              <button
                onClick={addGame}
                disabled={adding}
                data-testid="add-game-btn"
                className="inline-flex items-center gap-1.5 px-5 py-2.5 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] disabled:opacity-60 transition-colors"
              >
                <Plus size={14} /> {adding ? "Adding…" : "Add game"}
              </button>
            )}
          </div>
        </div>
      </section>

      <section className="mt-8">
        <div className="flex items-center gap-3 mb-3">
          <span className="grid place-items-center w-6 h-6 rounded-md bg-[#ffe4d1] text-[#ff6a00]">
            <Gamepad2 size={14} />
          </span>
          <h2 className="font-display font-bold text-lg tracking-tight">All games</h2>
          <span className="text-xs text-[#5c534d]">{games.length} of {totalCount}</span>
          <input
            type="text"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            placeholder="Filter…"
            data-testid="games-filter-input"
            className="ml-auto px-3 py-1.5 text-sm rounded-full border border-[#efe3d6] bg-white focus:outline-none focus:ring-2 focus:ring-[#ff6a00] focus:border-[#ff6a00] w-52"
          />
        </div>
        {games.length === 0 ? (
          <div className="text-sm text-[#5c534d] italic bg-white border border-dashed border-[#efe3d6] rounded-2xl px-4 py-6">
            {filter ? "No games match that filter." : "No games yet."}
          </div>
        ) : (
          <div className="bg-white border border-[#efe3d6] rounded-2xl divide-y divide-[#efe3d6] overflow-hidden max-h-[540px] overflow-y-auto">
            {games.map((g) => (
              <div
                key={g.slug}
                className="flex items-center justify-between gap-3 px-4 py-3"
                data-testid={`game-row-${g.slug}`}
              >
                <div className="min-w-0">
                  <div className="font-semibold text-[#1a1613] truncate">{g.name}</div>
                  <div className="text-xs text-[#5c534d] truncate">/{g.slug}</div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    onClick={() => beginEdit(g.slug)}
                    data-testid={`edit-game-${g.slug}`}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border border-[#efe3d6] text-xs font-semibold hover:border-[#ff6a00] hover:text-[#ff6a00] transition-colors"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => removeGame(g.slug, g.name)}
                    data-testid={`delete-game-${g.slug}`}
                    className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-full text-[#5c534d] hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Delete game"
                  >
                    <Trash2 size={13} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
};
